<script setup>
import {router} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';defineProps({orders:Object});const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);const statuses=['pending','paid','processing','shipped','completed','cancelled'];function update(o,e){router.patch(`/admin/pesanan/${o.id}`,{status:e.target.value})}
</script>
<template><AppLayout><div class="page"><h1 class="page-title">Kelola Pesanan</h1><p class="muted">Perbarui status transaksi pelanggan.</p><div class="panel"><table class="table"><thead><tr><th>Nomor</th><th>Pelanggan</th><th>Total</th><th>Pembayaran</th><th>Status</th></tr></thead><tbody><tr v-for="o in orders.data" :key="o.id"><td>{{o.order_number}}</td><td>{{o.customer_name}}<br><small class="muted">{{o.phone}}</small></td><td>{{money(o.total)}}</td><td>{{o.payment_method}}</td><td><select :value="o.status" @change="update(o,$event)" style="padding:8px;border:1px solid #dce2ed;border-radius:8px"><option v-for="s in statuses" :value="s">{{s}}</option></select></td></tr></tbody></table><div v-if="!orders.data.length" class="muted">Belum ada pesanan.</div></div></div></AppLayout></template>
